// domain/OrderConfirmationUseCase.ts
import Stripe from 'stripe';                          // npm package
import { IOrderRepository } from './ports/IOrderRepository';
import { IEmailNotifier } from './ports/IEmailNotifier';

export class OrderConfirmationUseCase implements OrderConfirmationPort {
  private stripe = new Stripe(process.env.STRIPE_KEY!);

  constructor(
    private orderRepo: IOrderRepository,
    private emailNotifier: IEmailNotifier,
  ) {}

  async confirmOrder(orderId: string, approverId: string): Promise<ConfirmationResult> {
    const order = await this.orderRepo.findById(orderId);
    if (!order) return ConfirmationResult.notFound();
    if (order.status !== 'pending') return ConfirmationResult.invalidStatus();

    // Direct Stripe call inside the domain use case
    const intent = await this.stripe.paymentIntents.create({
      amount: order.totalAmount.inCents(),
      currency: order.totalAmount.currency,
      customer: order.customerId,
    });

    if (intent.status !== 'succeeded') {
      return ConfirmationResult.paymentFailed(intent.status);
    }

    order.confirm(approverId, intent.id);
    await this.orderRepo.save(order);
    await this.emailNotifier.send(order.customerEmail, 'Order confirmed', `Charge: ${intent.id}`);
    return ConfirmationResult.success(intent.id);
  }
}
